function result = auditQualityAwareProposedDiagnostic20(root,varargin)
%AUDITQUALITYAWAREPROPOSEDDIAGNOSTIC20 Manual 11-method paired diagnostic.
parser=inputParser;parser.addParameter('dryRun',false,@(x)islogical(x)&&isscalar(x));parser.addParameter('outputDirectory','',@(x)ischar(x)||(isstring(x)&&isscalar(x)));parser.parse(varargin{:});options=parser.Results;
cfg=auditQualityAwareDiagnostic20Config(root);
if strlength(string(options.outputDirectory))==0
    if options.dryRun,out=[tempname '_quality_aware_diagnostic20_dryrun'];else,out=cfg.diagnosticOutput;end
else
    out=char(options.outputDirectory);
end
preflight=auditQualityAwareDiagnostic20Preflight(root,cfg,out);schema=auditQualityAwareDiagnostic20Schema();methods=cfg.diagnosticMethods;
stateContainers=cell(numel(methods),1);for index=1:numel(methods),stateContainers{index}=struct('method',methods(index),'ownerId',index);end
if options.dryRun
    if ~exist(out,'dir'),mkdir(out);end;tables=localDryTables(schema);result=struct('dryRun',true,'randomPhysicalPacketCount',0,'cfg',cfg,'methods',methods,'schema',schema,'tables',tables,'preflight',preflight,'stateContainers',{stateContainers},'outputDirectory',out);return;
end
if ~exist(out,'dir'),mkdir(out);end;loaded=load(cfg.covariancePath,'covariance');covariance=loaded.covariance;rng(cfg.diagnosticMasterSeed,'twister');
physicalCount=numel(cfg.Ncodeword)*cfg.diagnosticPacketCountPerCondition;methodCount=numel(methods);packetCells=cell(physicalCount*methodCount,1);hashCells=cell(physicalCount*methodCount,1);qualityCells=cell(physicalCount*3,1);candidateCells=cell(physicalCount,1);targetCells=cell(physicalCount,1);packetCursor=0;rowCursor=0;qualityCursor=0;wall=tic;
for conditionIndex=1:numel(cfg.Ncodeword)
    nCodeword=cfg.Ncodeword(conditionIndex);conditionSeed=cfg.diagnosticMasterSeed+100000*nCodeword;
    for packetIndex=1:cfg.diagnosticPacketCountPerCondition
        packetSeed=conditionSeed+packetIndex;rng(packetSeed,'twister');packet=auditQualityAwareMiniPacket(cfg,nCodeword);packetCursor=packetCursor+1;
        legacy=auditQualityAwareLegacyCausalEstimates(cfg,packet,[1 2 3]);online=struct('pilotObservation',packet.obs,'receivedData',packet.y,'dataSubcarriers',cfg.data,'validDataMask',packet.validReMask,'noiseVar',cfg.noiseVar,'rho',cfg.rho);quality=auditQualityAwareProposedCausalEstimates(cfg,online);
        estimates={legacy.Hbase,legacy.Hold,legacy.HfixedRadius1,legacy.HfixedRadius2,legacy.HfixedRadius3,quality.channelEstimates{2},quality.channelEstimates{3},quality.channelEstimates{4},[],legacy.Horacle,packet.H};
        times=[legacy.baseAudit.baseEstimationTimeSec legacy.baseAudit.proposedEstimationTimeSec legacy.fixedAudit1.runtimeSeconds legacy.fixedAudit2.runtimeSeconds legacy.fixedAudit3.runtimeSeconds quality.branchRuntimeSeconds(2:4).' 0 legacy.oracleAudit.runtimeSeconds 0];
        fixedAudits={[],[],legacy.fixedAudit1,legacy.fixedAudit2,legacy.fixedAudit3,[],[],[],[],[],[]};qualityAudits={[],[],[],[],[],quality.stateAudits{2},quality.stateAudits{3},quality.stateAudits{4},[],[],[]};
        solverFailureOverrides=[NaN 0 legacy.fixedAudit1.solverFailureCount legacy.fixedAudit2.solverFailureCount legacy.fixedAudit3.solverFailureCount quality.stateAudits{2}.solverFailureCount quality.stateAudits{3}.solverFailureCount quality.stateAudits{4}.solverFailureCount NaN legacy.oracleAudit.solverFailureCount NaN];
        for methodIndex=1:methodCount
            try
                metric=auditQualityAwareMiniDecode(cfg,packet,estimates{methodIndex},times(methodIndex),covariance);
            catch exception
                error('Diagnostic20 failed: payloadSymbols=%d packetIndex=%d method=%s symbolIndex=NaN targetSubcarrier=NaN candidateRadius=NaN. %s',packet.Npayload,packetIndex,methods(methodIndex),exception.message);
            end
            if methodIndex~=9,metric.solverFailureCount=solverFailureOverrides(methodIndex);end
            metric=localDiagnosticFields(metric,fixedAudits{methodIndex},qualityAudits{methodIndex});metric.payloadSymbols=packet.Npayload;metric.nCodeword=nCodeword;metric.packetIndex=packetIndex;metric.method=methods(methodIndex);metric=localAttachHashes(metric,packet.hashes);rowCursor=rowCursor+1;packetCells{rowCursor}=struct2table(metric,'AsArray',true);hashCells{rowCursor}=localHashRow(packet,packetIndex,methods(methodIndex),conditionSeed,packetSeed);
        end
        for q=2:4,qualityCursor=qualityCursor+1;qualityCells{qualityCursor}=localQualityRow(packet.Npayload,packetIndex,methods(q+4),quality.stateAudits{q});end
        offline=auditEvaluateQualityWindowAgainstTruthOffline(quality.stateAudits{4},packet.H,cfg.data,packet.Npayload,packetIndex,cfg.trueErrorTieTolerance);candidateCells{packetCursor}=offline.candidateTable;targetCells{packetCursor}=offline.targetTable;
    end
end
packetTable=vertcat(packetCells{:});packetTable=packetTable(:,schema.packet);pairingTable=vertcat(hashCells{:});qualityTable=vertcat(qualityCells{:});candidateTable=vertcat(candidateCells{:});targetTable=vertcat(targetCells{:});localAssertPairing(pairingTable,methodCount);
summaryTable=localSummary(packetTable);pairedTable=localPaired(packetTable);calibrationTable=auditSummarizeQualityWindowCalibration(candidateTable,targetTable,cfg.trueErrorTieTolerance);
writetable(packetTable,fullfile(out,'quality_aware_diagnostic20_packet_level.csv'));writetable(summaryTable,fullfile(out,'quality_aware_diagnostic20_summary.csv'));writetable(pairedTable,fullfile(out,'quality_aware_diagnostic20_paired_statistics.csv'));writetable(pairingTable,fullfile(out,'quality_aware_diagnostic20_pairing_hashes.csv'));writetable(qualityTable,fullfile(out,'quality_aware_diagnostic20_window_selection_audit.csv'));writetable(qualityTable,fullfile(out,'quality_aware_diagnostic20_rda_distribution_audit.csv'));writetable(qualityTable,fullfile(out,'quality_aware_diagnostic20_rejection_reason_audit.csv'));writetable(candidateTable,fullfile(out,'quality_aware_diagnostic20_true_window_candidate_audit.csv'));writetable(calibrationTable,fullfile(out,'quality_aware_diagnostic20_selection_calibration_summary.csv'));
wallTime=toc(wall);localReport(out,cfg,packetTable,wallTime,preflight);result=struct('dryRun',false,'randomPhysicalPacketCount',packetCursor,'packetTable',packetTable,'summaryTable',summaryTable,'pairedTable',pairedTable,'pairingTable',pairingTable,'qualityTable',qualityTable,'candidateTable',candidateTable,'targetTable',targetTable,'calibrationTable',calibrationTable,'outputDirectory',out);
end

function tables=localDryTables(schema),names=fieldnames(schema);tables=struct();for i=1:numel(names),tables.(names{i})=cell2table(cell(0,numel(schema.(names{i}))),'VariableNames',schema.(names{i}));end,end
function metric=localAttachHashes(metric,h),names=fieldnames(h);for i=1:numel(names),metric.(names{i})=h.(names{i});end,end
function T=localHashRow(packet,packetIndex,method,conditionSeed,packetSeed),h=packet.hashes;s=auditQualityAwareMiniSchema();T=table(packet.Npayload,packet.nCodeword,packetIndex,method,conditionSeed,packetSeed,h.informationBitsHash,h.transmitBitsHash,h.codedBitsHash,h.qamSymbolsHash,h.paddingMaskHash,h.channelHash,h.noiseHash,h.receivedSignalHash,h.pilotObservationHash,'VariableNames',s.hash);end
function metric=localDiagnosticFields(metric,fixed,quality)
names={'covarianceNonPsdCount','daUpdateCount','noCandidateCount','innovationRejectCount','configuredRadius','candidateFeasibleCount','candidateRejectedCount','daUpdateCoverageRate','selectedRadius1Count','selectedRadius2Count','selectedRadius3Count','selectionRateRadius1','selectionRateRadius2','selectionRateRadius3','meanRdaTrace','medianRdaTrace','p95RdaTrace','meanNormalizedNis','p95NormalizedNis','meanDecisionInflation','meanNisInflation'};for i=1:numel(names),metric.(names{i})=NaN;end
if ~isempty(fixed),metric.configuredRadius=fixed.configuredRadius;metric.candidateFeasibleCount=fixed.candidateFeasibleCount;metric.candidateRejectedCount=fixed.candidateRejectedCount;metric.daUpdateCoverageRate=fixed.daUpdateCoverageRate;metric.daUpdateCount=fixed.accepted;metric.noCandidateCount=fixed.rejected;metric.covarianceNonPsdCount=0;metric.innovationRejectCount=0;end
if ~isempty(quality),radius=quality.selectedRadiusCount;rate=radius/max(sum(radius),1);cursor=quality.candidateAuditCursor;metric.covarianceNonPsdCount=quality.covarianceNonPsdCount;metric.daUpdateCount=nnz(quality.daUpdateCount);metric.noCandidateCount=quality.noCandidateCount;metric.innovationRejectCount=quality.innovationRejectCount;metric.selectedRadius1Count=radius(1);metric.selectedRadius2Count=radius(2);metric.selectedRadius3Count=radius(3);metric.selectionRateRadius1=rate(1);metric.selectionRateRadius2=rate(2);metric.selectionRateRadius3=rate(3);metric.meanRdaTrace=localStat(quality.rdaTrace(1:cursor),'mean');metric.medianRdaTrace=localStat(quality.rdaTrace(1:cursor),'median');metric.p95RdaTrace=localPercentile(quality.rdaTrace(1:cursor),.95);metric.meanNormalizedNis=localStat(quality.normalizedNis(1:cursor),'mean');metric.p95NormalizedNis=localPercentile(quality.normalizedNis(1:cursor),.95);metric.meanDecisionInflation=localStat(quality.decisionInflation(1:cursor),'mean');metric.meanNisInflation=localStat(quality.nisInflation(1:cursor),'mean');end
end
function T=localQualityRow(payload,packet,method,a),radius=a.selectedRadiusCount;rate=radius/max(sum(radius),1);c=a.candidateAuditCursor;T=table(payload,packet,method,radius(1),radius(2),radius(3),rate(1),rate(2),rate(3),a.noCandidateCount,a.innovationRejectCount,a.candidateCountBeforeInnovation,a.candidateCountAfterInnovation,a.innovationRejectCount/max(a.candidateCountBeforeInnovation,1),localStat(a.rdaTrace(1:c),'mean'),localStat(a.rdaTrace(1:c),'median'),localPercentile(a.rdaTrace(1:c),.95),localStat(a.normalizedNis(1:c),'mean'),localPercentile(a.normalizedNis(1:c),.95),localStat(a.decisionInflation(1:c),'mean'),localStat(a.nisInflation(1:c),'mean'),a.eigenFloorAppliedCount,a.solverFailureCount,a.covarianceNonPsdCount,nnz(a.daUpdateCount),a.pilotUpdateCount,'VariableNames',{'payloadSymbols','packetIndex','method','selectedRadius1Count','selectedRadius2Count','selectedRadius3Count','selectionRateRadius1','selectionRateRadius2','selectionRateRadius3','noCandidateCount','innovationRejectCount','candidateCountBeforeInnovation','candidateCountAfterInnovation','innovationRejectRate','meanRdaTrace','medianRdaTrace','p95RdaTrace','meanNormalizedNis','p95NormalizedNis','meanDecisionInflation','meanNisInflation','eigenFloorAppliedCount','solverFailureCount','covarianceNonPsdCount','daUpdateCount','pilotUpdateCount'});end
function localAssertPairing(T,count),keys=unique(T(:,{'payloadSymbols','packetIndex'}),'rows');s=auditQualityAwareMiniSchema();hashes=s.hash(7:end);for i=1:height(keys),rows=T(T.payloadSymbols==keys.payloadSymbols(i)&T.packetIndex==keys.packetIndex(i),:);assert(height(rows)==count);for j=1:numel(hashes),v=rows.(hashes{j});assert(all(v==v(1)));end,end,end
function T=localSummary(R),groups=unique(R(:,{'payloadSymbols','method'}),'rows');cells=cell(height(groups),1);for i=1:height(groups),p=R(R.payloadSymbols==groups.payloadSymbols(i)&R.method==groups.method(i),:);cells{i}=table(groups.payloadSymbols(i),groups.method(i),height(p),mean(p.csiNmse),median(p.csiNmse),mean(p.preLdpcBer),median(p.preLdpcBer),sum(p.totalCodewordCount),sum(p.passedCodewordCount),sum(p.passedCodewordCount)/max(sum(p.totalCodewordCount),1),mean(p.payloadGoodputMbps),mean(p.runtimeSeconds),median(p.runtimeSeconds),nnz(p.hasNaN),nnz(p.hasInf),sum(p.futureSymbolReadCount),sum(p.testTruthOnlineUseCount),'VariableNames',auditQualityAwareMiniSchema().summary);end;T=vertcat(cells{:});end
function T=localPaired(R)
comparisons=["OldMinFeasibleCausal_EP","BaseKalmanCausal_EP";"FixedRadius1Causal_EP","BaseKalmanCausal_EP";"FixedRadius2Causal_EP","BaseKalmanCausal_EP";"FixedRadius3Causal_EP","BaseKalmanCausal_EP";"FixedRadius2Causal_EP","FixedRadius1Causal_EP";"FixedRadius3Causal_EP","FixedRadius2Causal_EP";"QualityWindowOnlyCausal_EP","OldMinFeasibleCausal_EP";"QualityWindowOnlyCausal_EP","FixedRadius1Causal_EP";"QualityWindowOnlyCausal_EP","FixedRadius2Causal_EP";"QualityWindowOnlyCausal_EP","FixedRadius3Causal_EP";"AdaptiveRdaFixedR2Causal_EP","FixedRadius2Causal_EP";"QualityAwareLocalDAKalmanCausal_EP","BaseKalmanCausal_EP";"QualityAwareLocalDAKalmanCausal_EP","OldMinFeasibleCausal_EP";"QualityAwareLocalDAKalmanCausal_EP","FixedRadius1Causal_EP";"QualityAwareLocalDAKalmanCausal_EP","FixedRadius2Causal_EP";"QualityAwareLocalDAKalmanCausal_EP","FixedRadius3Causal_EP";"QualityAwareLocalDAKalmanCausal_EP","QualityWindowOnlyCausal_EP";"QualityAwareLocalDAKalmanCausal_EP","AdaptiveRdaFixedR2Causal_EP";"QualityAwareLocalDAKalmanCausal_EP","OJCD_LMMSE_EP_Adapted";"QualityAwareLocalDAKalmanCausal_EP","OracleDataAidedCausal_EP"];
metrics=["csiNmse","preLdpcBer","blockErrorRate","codewordPassRate","payloadGoodputMbps","runtimeSeconds"];higher=[false false false true true false];cells=cell(2*size(comparisons,1)*numel(metrics),1);cursor=0;names={'payloadSymbols','methodA','methodB','metric','pairedPacketCount','meanDelta','medianDelta','minimumDelta','maximumDelta','winCount','tieCount','lossCount'};
for payload=unique(R.payloadSymbols).',for c=1:size(comparisons,1),for m=1:numel(metrics),a=sortrows(R(R.payloadSymbols==payload&R.method==comparisons(c,1),:),'packetIndex');b=sortrows(R(R.payloadSymbols==payload&R.method==comparisons(c,2),:),'packetIndex');d=a.(metrics(m))-b.(metrics(m));tol=1e-15;if higher(m),win=nnz(d>tol);loss=nnz(d<-tol);else,win=nnz(d<-tol);loss=nnz(d>tol);end;cursor=cursor+1;cells{cursor}=table(payload,comparisons(c,1),comparisons(c,2),metrics(m),numel(d),mean(d),median(d),min(d),max(d),win,numel(d)-win-loss,loss,'VariableNames',names);end,end,end;T=vertcat(cells{1:cursor});
end
function localReport(out,cfg,R,wall,preflight),file=fopen(fullfile(out,'quality_aware_diagnostic20_run_report.txt'),'w','n','UTF-8');assert(file>=0);cleanup=onCleanup(@()fclose(file));fprintf(file,'Quality-aware diagnostic20, diagnostic evidence only. seed=%d packetsPerCondition=%d Npayload=%s methods=%s\nmethodRows=%d wallTimeSec=%.9g NaN=%d Inf=%d futureReads=%g truthOnlineUses=%g protected=%d MJCD/OJCD=%.17g\nH_true is used only after all online methods and decoding for the packet finish.\n',cfg.diagnosticMasterSeed,cfg.diagnosticPacketCountPerCondition,mat2str(cfg.Npayload),strjoin(cfg.diagnosticMethods,','),height(R),wall,nnz(R.hasNaN),nnz(R.hasInf),sum(R.futureSymbolReadCount),sum(R.testTruthOnlineUseCount),preflight.protectedHashesPass,preflight.mjcdOjcdRelativeDifference);end
function value=localStat(data,kind),data=data(isfinite(data));if isempty(data),value=NaN;else,value=feval(kind,data);end,end
function value=localPercentile(data,p),data=sort(data(isfinite(data)));if isempty(data),value=NaN;return;end;position=1+(numel(data)-1)*p;lo=floor(position);hi=ceil(position);value=data(lo)+(position-lo)*(data(hi)-data(lo));end
